SELECT id, book_id, user_id, username, rating, content, created_at, updated_at
FROM book_review
WHERE id = #{id}

SELECT id, book_id, user_id, username, rating, content, created_at, updated_at
FROM book_review
WHERE book_id = #{bookId} AND user_id = #{userId}

SELECT id, book_id, user_id, username, rating, content, created_at, updated_at FROM book_review WHERE book_id = #{bookId} ORDER BY
rating ASC, created_at DESC rating DESC, created_at DESC created_at ASC created_at DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE book_review
SET rating = #{rating},
    content = #{content}
WHERE id = #{id}
